float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
uniform float amzp_alphaComp;
uniform float amzp_preset;
uniform float amzp_count;
layout(color) uniform half4 amzp_c1;
layout(color) uniform half4 amzp_c2;
layout(color) uniform half4 amzp_c3;
layout(color) uniform half4 amzp_c4;
layout(color) uniform half4 amzp_c5;
layout(color) uniform half4 amzp_c6;
layout(color) uniform half4 amzp_c7;
layout(color) uniform half4 amzp_c8;
layout(color) uniform half4 amzp_c9;
layout(color) uniform half4 amzp_c10;
uniform float amzp_anchor;
uniform float amzp_margin;
uniform float amzp_orient;
uniform float amzp_blockW;
uniform float amzp_blockH;
uniform float amzp_gap;
uniform float amzp_radius;
uniform float amzp_featherX;
uniform float amzp_featherY;
uniform float amzp_border;
layout(color) uniform half4 amzp_borderCol;
uniform float amzp_showBar;
layout(color) uniform half4 amzp_barCol;
uniform float amzp_barPad;
uniform float amzp_barRadius;
uniform float amzp_shadowAmt;
uniform float amzp_shadowSize;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float2 nmStd(float2 p, float pxk) {
        float z = max(amzp_scale * 2.0, 0.002);
        p -= amzp_position * pxk;
        p = nmRot(p, -radians(amzp_angle));
        return p / (z * max(amzp_stretch, float2(0.01)));
    }
    float2 nmStdUp(float2 d, float pxk) { float2 p = nmStd(float2(d.x, -d.y), pxk); return float2(p.x, -p.y); }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx * amzp_hardness, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        if (int(amzp_blendMode) == 0) return f;
        if (int(amzp_blendMode) == 1) return float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        if (int(amzp_blendMode) == 2) return float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        return f + b * (1.0 - f.a);
    }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float presetCount() {
        if (int(amzp_preset) == 2) return 2.0;
        if (int(amzp_preset) == 3) return 4.0;
        if (int(amzp_preset) == 4) return 4.0;
        if (int(amzp_preset) == 5) return 4.0;
        if (int(amzp_preset) == 6) return 4.0;
        if (int(amzp_preset) == 7) return 4.0;
        if (int(amzp_preset) == 8) return 3.0;
        if (int(amzp_preset) == 9) return 4.0;
        if (int(amzp_preset) == 10) return 4.0;
        if (int(amzp_preset) == 11) return 3.0;
        if (int(amzp_preset) == 12) return 4.0;
        if (int(amzp_preset) == 13) return 3.0;
        if (int(amzp_preset) == 14) return 4.0;
        return floor(clamp(amzp_count, 1.0, 10.0) + 0.5);
    }
    float3 customCol(int k) { if (k == 0) return amzp_c1.rgb; if (k == 1) return amzp_c2.rgb; if (k == 2) return amzp_c3.rgb; if (k == 3) return amzp_c4.rgb; if (k == 4) return amzp_c5.rgb; if (k == 5) return amzp_c6.rgb; if (k == 6) return amzp_c7.rgb; if (k == 7) return amzp_c8.rgb; if (k == 8) return amzp_c9.rgb; return amzp_c10.rgb; }
    float3 presetCol(int k) {
        if (int(amzp_preset) == 2) { if (k == 0) return float3(0.1176, 0.1333, 0.2235); if (k == 1) return float3(0.0000, 1.0000, 0.6588); return float3(0.0000, 1.0000, 0.6588); }
        if (int(amzp_preset) == 3) { if (k == 0) return float3(0.4078, 0.2980, 0.2549); if (k == 1) return float3(0.3098, 0.6392, 0.6471); if (k == 2) return float3(0.9922, 0.6824, 0.2196); if (k == 3) return float3(0.9686, 0.3294, 0.2078); return float3(0.9686, 0.3294, 0.2078); }
        if (int(amzp_preset) == 4) { if (k == 0) return float3(1.0000, 0.8902, 0.7020); if (k == 1) return float3(1.0000, 0.7882, 0.4510); if (k == 2) return float3(0.1882, 0.6275, 0.8784); if (k == 3) return float3(0.0000, 0.4196, 0.7255); return float3(0.0000, 0.4196, 0.7255); }
        if (int(amzp_preset) == 5) { if (k == 0) return float3(0.9294, 0.4196, 0.3569); if (k == 1) return float3(0.2275, 0.2431, 0.3490); if (k == 2) return float3(0.9765, 0.6745, 0.4000); if (k == 3) return float3(0.9255, 0.9020, 0.8078); return float3(0.9255, 0.9020, 0.8078); }
        if (int(amzp_preset) == 6) { if (k == 0) return float3(0.9843, 0.5804, 0.5608); if (k == 1) return float3(0.9490, 0.7922, 0.7843); if (k == 2) return float3(0.7647, 0.4196, 0.5176); if (k == 3) return float3(0.9961, 0.7333, 0.4588); return float3(0.9961, 0.7333, 0.4588); }
        if (int(amzp_preset) == 7) { if (k == 0) return float3(1.0000, 0.9725, 0.9098); if (k == 1) return float3(0.9843, 0.8353, 0.5020); if (k == 2) return float3(0.8353, 0.1608, 0.2549); if (k == 3) return float3(0.6039, 0.0471, 0.2039); return float3(0.6039, 0.0471, 0.2039); }
        if (int(amzp_preset) == 8) { if (k == 0) return float3(0.1529, 0.1843, 0.2588); if (k == 1) return float3(0.5922, 0.6118, 0.7020); if (k == 2) return float3(0.9451, 0.1804, 0.2353); return float3(0.9451, 0.1804, 0.2353); }
        if (int(amzp_preset) == 9) { if (k == 0) return float3(0.1412, 0.4157, 0.4471); if (k == 1) return float3(0.2118, 0.5608, 0.5451); if (k == 2) return float3(0.9569, 0.8745, 0.7686); if (k == 3) return float3(0.8706, 0.7451, 0.6627); return float3(0.8706, 0.7451, 0.6627); }
        if (int(amzp_preset) == 10) { if (k == 0) return float3(0.1216, 0.7490, 0.3333); if (k == 1) return float3(0.0471, 0.3098, 0.4235); if (k == 2) return float3(0.0039, 0.7294, 0.9412); if (k == 3) return float3(0.4588, 0.4588, 0.4588); return float3(0.4588, 0.4588, 0.4588); }
        if (int(amzp_preset) == 11) { if (k == 0) return float3(0.2745, 0.1529, 0.2157); if (k == 1) return float3(0.9686, 0.7255, 0.1412); if (k == 2) return float3(0.9059, 0.5255, 0.1529); return float3(0.9059, 0.5255, 0.1529); }
        if (int(amzp_preset) == 12) { if (k == 0) return float3(0.2863, 0.2745, 0.4588); if (k == 1) return float3(0.4745, 0.4745, 0.6157); if (k == 2) return float3(1.0000, 0.7569, 0.0784); if (k == 3) return float3(1.0000, 0.8314, 0.3294); return float3(1.0000, 0.8314, 0.3294); }
        if (int(amzp_preset) == 13) { if (k == 0) return float3(1.0000, 0.7137, 0.6392); if (k == 1) return float3(0.9608, 0.8431, 0.8000); if (k == 2) return float3(0.3059, 0.3059, 0.2902); return float3(0.3059, 0.3059, 0.2902); }
        if (int(amzp_preset) == 14) { if (k == 0) return float3(0.9804, 0.4157, 0.5020); if (k == 1) return float3(1.0000, 0.1882, 0.3098); if (k == 2) return float3(0.3176, 0.5490, 0.9059); if (k == 3) return float3(0.0000, 1.0000, 1.0000); return float3(0.0000, 1.0000, 1.0000); }
        return customCol(k);
    }
    float3 layerCol(int k) {
        float fk = float(k);
        float2 pt = float2(fract(0.5 + fk * 0.618034), fract(0.31 + fk * 0.381966 * 1.7));
        pt = mix(float2(0.1), float2(0.9), pt);
        float4 acc = float4(0.0);
        for (int i = 0; i < 5; i++) {
            float a = float(i) * 1.2566371;
            float2 o = i == 0 ? float2(0.0) : float2(cos(a), sin(a)) * 0.025;
            acc += layerAt(pt + o);
        }
        return acc.a > 0.0001 ? acc.rgb / acc.a : float3(0.0);
    }
    float3 blockCol(int k) {
        if (int(amzp_preset) == 1) return layerCol(k);
        return presetCol(k);
    }
    float sdRB(float2 p, float2 b, float r) {
        r = min(r, min(b.x, b.y));
        float2 q = abs(p) - b + r;
        return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
    }
    float4 over(float4 top, float4 bot) { return top + bot * (1.0 - top.a); }
    void amzRender() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float4 orig = layerAt(uv);
        float ps = pxs();
        float N = presetCount();
        float bw = amzp_blockW * ps, bh = amzp_blockH * ps, gp = amzp_gap * ps, pad = (amzp_showBar>0.5) ? amzp_barPad * ps : 0.0;
        bool vert = int(amzp_orient) == 1;
        float cw = N * bw + (N - 1.0) * gp;
        float2 bar = vert ? float2(bw, N * bh + (N - 1.0) * gp) : float2(cw, bh);
        float2 barS = bar + 2.0 * pad;
        float2 stz = max(amzp_scale * 2.0, 0.002) * max(amzp_stretch, float2(0.01));
        float2 hs = 0.5 * barS * stz;
        float m = amzp_margin * ps;
        float2 amzLocal_pos = 0.5 * W;
        if (int(amzp_anchor) == 0) amzLocal_pos = float2(0.5 * W.x, m + hs.y);
        else if (int(amzp_anchor) == 1) amzLocal_pos = float2(0.5 * W.x, W.y - m - hs.y);
        else if (int(amzp_anchor) == 3) amzLocal_pos = float2(m + hs.x, 0.5 * W.y);
        else if (int(amzp_anchor) == 4) amzLocal_pos = float2(W.x - m - hs.x, 0.5 * W.y);
        else if (int(amzp_anchor) == 5) amzLocal_pos = float2(m + hs.x, m + hs.y);
        else if (int(amzp_anchor) == 6) amzLocal_pos = float2(W.x - m - hs.x, m + hs.y);
        else if (int(amzp_anchor) == 7) amzLocal_pos = float2(m + hs.x, W.y - m - hs.y);
        else if (int(amzp_anchor) == 8) amzLocal_pos = float2(W.x - m - hs.x, W.y - m - hs.y);
        float2 lp = nmStdUp(uv * W - amzLocal_pos, ps);
        float aa = 1.0 / min(stz.x, stz.y);
        float4 G = float4(0.0);
        if ((amzp_showBar>0.5)) {
            float ss = max(amzp_shadowSize * ps, 0.5);
            float dsh = sdRB(lp - float2(0.0, -ss * 0.35), 0.5 * barS, amzp_barRadius * ps);
            float sa = (1.0 - smoothstep(-ss, ss, dsh)) * amzp_shadowAmt;
            G = float4(0.0, 0.0, 0.0, sa);
            float db = sdRB(lp, 0.5 * barS, amzp_barRadius * ps);
            float ba = (1.0 - smoothstep(-aa, aa, db)) * amzp_barCol.a;
            G = over(float4(amzp_barCol.rgb * ba, ba), G);
        }
        float along = vert ? -lp.y : lp.x;
        float L = vert ? bar.y : cw;
        float step1 = (vert ? bh : bw) + gp;
        float fi = clamp(floor((along + 0.5 * L + 0.5 * gp) / step1), 0.0, N - 1.0);
        float cpos = -0.5 * L + (vert ? bh : bw) * 0.5 + fi * step1;
        float2 bc = vert ? float2(0.0, -cpos) : float2(cpos, 0.0);
        float d = sdRB(lp - bc, float2(bw, bh) * 0.5, amzp_radius * ps);
        float a = 1.0 - smoothstep(-aa, aa, d);
        float2 fe = max(float2(amzp_featherX, amzp_featherY), float2(0.0)) * ps;
        float2 pb = abs(lp - bc);
        float2 ed = float2(bw, bh) * 0.5 - pb;
        if (fe.x > 0.001) a *= smoothstep(0.0, fe.x, ed.x);
        if (fe.y > 0.001) a *= smoothstep(0.0, fe.y, ed.y);
        float3 col = blockCol(int(fi + 0.5));
        float bd = amzp_border * ps;
        if (bd > 0.0) {
            float inner = 1.0 - smoothstep(-aa, aa, d + bd);
            col = mix(amzp_borderCol.rgb, col, inner);
        }
        G = over(float4(col * a, a), G);
        amzOutput = nmBlend(orig, G);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
